import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type BetterSqlite3 from "better-sqlite3";
import type { Rule } from "../../src/shared/rules.ts";

/**
 * The fixed performance fixtures (spec §10.2, §10.5).
 *
 * The Game data is generated from a committed seed, never from the clock or
 * `Math.random`. `fixtureChecksum` pins the generated bytes so an accidental
 * edit to the generator cannot silently change the benchmark baseline.
 */

const HERE = dirname(fileURLToPath(import.meta.url));
const RULES_PATH = join(HERE, "..", "..", "tests", "fixtures", "perf", "rules-100.json");

export const PERF_20000 = { games: 20_000, seed: 0x0038_2000, baseAppId: 500_000 } as const;
export const PERF_1300 = { games: 1_300, seed: 0x0038_1300, baseAppId: 600_000 } as const;

export interface PerfRuleFixture {
  name: string;
  rules: Rule[];
}

/** Read the committed 100-Rule Smart Collection used by the evaluator budget. */
export function readRulesFixture(): PerfRuleFixture {
  const document = JSON.parse(readFileSync(RULES_PATH, "utf8")) as PerfRuleFixture;
  return { name: document.name, rules: document.rules };
}

export interface PerfGame {
  appId: number;
  name: string;
  nameKey: string;
  ownershipStatus: "owned" | "local_only" | "unknown";
  installed: boolean | null;
  playtimeMinutes: number;
  lastPlayedAt: number | null;
  releaseYear: number | null;
  metacriticScore: number | null;
  reviewScore: number | null;
  reviewTier: string | null;
  reviewCount: number | null;
  storefrontType: string | null;
  platforms: { windows: boolean; mac: boolean; linux: boolean };
  genres: string[];
  categories: string[];
  developers: string[];
  publishers: string[];
  tags: string[];
  steamCollections: string[];
}

export interface PerfSmartCollection {
  id: string;
  name: string;
  rules: Rule[];
}

